import { MemberVault } from "../store/MemberVault.js";
import { PolicyRoleIndex, finalizeMemberRemoval } from "../policy/PolicyRoleIndex.js";
import { OfflineMutationQueue } from "../queue/OfflineMutationQueue.js";
import { DeltaStream } from "../sync/DeltaStream.js";

let mutationSequence = 0;

function nextMutationId(kind) {
  mutationSequence += 1;
  return kind + "-" + Date.now().toString(36) + "-" + mutationSequence;
}

export function createWorkspaceMemberActions(options = {}) {
  const { vault, policyRoleIndex, queue, isOffline = () => false } = options;
  if (!vault || !policyRoleIndex || !queue) throw new Error("createWorkspaceMemberActions 需要 vault、policyRoleIndex 与 queue");

  queue.subscribe((event) => {
    const mutation = event.mutation;
    if (!mutation) return;
    if (mutation.kind === "deleteWorkspaceMember") {
      if (event.type === "mutation.succeeded") {
        // 正常成功与幂等成功（MEMBER_NOT_FOUND 视为已应用）统一走 finalize：
        // 先记录成员墓碑序号再删除成员（vault.removeMember 内部顺序），并同步清理角色索引与审批转交链。
        for (const memberId of mutation.memberIds) {
          finalizeMemberRemoval(memberId, { vault, policyRoleIndex, mutationSeq: event.result.appliedSeq });
        }
        return;
      }
      for (const snapshot of mutation.rollbackMembers ?? []) {
        vault.restoreMember(snapshot);
        vault.setLastError(snapshot.id, event.error?.message || "删除失败");
      }
      return;
    }
    if (mutation.kind === "assignWorkspaceMemberRole" && event.type === "mutation.failed") {
      const memberId = mutation.memberIds[0];
      if (mutation.previousRole === null) policyRoleIndex.removeRole(memberId);
      else policyRoleIndex.setRole(memberId, mutation.previousRole);
    }
  });

  async function flushPendingMutations() {
    if (isOffline()) return null;
    try {
      return await queue.flush();
    } catch (error) {
      return { appliedSeq: null, succeeded: [], failed: [], error };
    }
  }

  async function deleteMembers(memberIds) {
    const candidates = Array.isArray(memberIds) ? memberIds : [memberIds];
    const ids = [...new Set(candidates)].filter((id) => typeof id === "string" && vault.hasMember(id));
    if (ids.length === 0) return { queued: [], flushed: false, error: null };
    const rollbackMembers = ids.map((id) => vault.getMember(id)).filter(Boolean);
    for (const id of ids) vault.setPendingAction(id, "delete");
    const mutation = {
      id: nextMutationId("delete-members"),
      kind: "deleteWorkspaceMember",
      memberIds: ids,
      rollbackMembers,
      // 幂等成功声明：服务器以 idempotent 形式返回 MEMBER_NOT_FOUND（成员已在其侧删除）时，
      // 由 OfflineMutationQueue.#declaresIdempotentSuccess 判定为已应用，
      // 避免网络抖动后的重试被误判为失败而回滚复活成员。
      successData: [{ code: "MEMBER_NOT_FOUND", behavior: "treatAsApplied" }],
      createdAt: Date.now(),
    };
    queue.enqueue(mutation);
    const report = await flushPendingMutations();
    return { queued: ids, flushed: report !== null, error: report?.error ?? null };
  }

  async function assignRole(memberId, roleId) {
    const previousRole = policyRoleIndex.getRole(memberId);
    policyRoleIndex.setRole(memberId, roleId);
    const mutation = {
      id: nextMutationId("assign-role"),
      kind: "assignWorkspaceMemberRole",
      memberIds: [memberId],
      payload: { roleId },
      previousRole,
      createdAt: Date.now(),
    };
    queue.enqueue(mutation);
    const report = await flushPendingMutations();
    return { queued: [memberId], flushed: report !== null, error: report?.error ?? null };
  }

  return { deleteMembers, assignRole, flushPendingMutations };
}

export function createWorkspaceRuntime(options = {}) {
  const vault = options.vault ?? new MemberVault(options.members ?? []);
  const policyRoleIndex = options.policyRoleIndex ?? new PolicyRoleIndex(options.policy ?? {});
  const queue = options.queue ?? new OfflineMutationQueue({ transport: options.transport, batchSize: options.batchSize });
  const isOffline = typeof options.isOffline === "function" ? options.isOffline : () => false;
  const actions = createWorkspaceMemberActions({ vault, policyRoleIndex, queue, isOffline });
  const stream = options.stream ?? new DeltaStream({ vault, policyRoleIndex });
  return { vault, policyRoleIndex, queue, stream, actions, deleteMembers: actions.deleteMembers, assignRole: actions.assignRole, flushPendingMutations: actions.flushPendingMutations };
}

export const WORKSPACE_ROLE_IDS = Object.freeze(["owner", "admin", "approver", "manager", "member"]);

export class PolicyRoleIndexError extends Error {
  constructor(code, message) {
    super(message);
    this.name = "PolicyRoleIndexError";
    this.code = code;
  }
}

export class PolicyRoleIndex {
  #roleByMemberId = new Map();
  #delegateByMemberId = new Map();

  constructor(options = {}) {
    for (const [memberId, roleId] of Object.entries(options.roleByMemberId ?? {})) this.setRole(memberId, roleId);
    for (const [memberId, delegateId] of Object.entries(options.delegateByMemberId ?? {})) this.delegateApproval(memberId, delegateId);
  }

  getRole(memberId) { return this.#roleByMemberId.get(memberId) ?? null; }

  hasRole(memberId) { return this.#roleByMemberId.has(memberId); }

  listRoles() {
    return [...this.#roleByMemberId.entries()].map(([memberId, roleId]) => ({ memberId, roleId })).sort((left, right) => left.memberId.localeCompare(right.memberId));
  }

  setRole(memberId, roleId) {
    if (typeof memberId !== "string" || memberId.length === 0) throw new PolicyRoleIndexError("ROLE_INDEX_MEMBER_INVALID", "成员 id 必须是非空字符串");
    if (!WORKSPACE_ROLE_IDS.includes(roleId)) throw new PolicyRoleIndexError("ROLE_INDEX_ROLE_INVALID", "未知工作区角色：" + roleId);
    this.#roleByMemberId.set(memberId, roleId);
    return roleId;
  }

  removeRole(memberId) { return this.#roleByMemberId.delete(memberId); }

  getDelegate(memberId) { return this.#delegateByMemberId.get(memberId) ?? null; }

  listDelegations() {
    return [...this.#delegateByMemberId.entries()].map(([memberId, delegateId]) => ({ memberId, delegateId })).sort((left, right) => left.memberId.localeCompare(right.memberId));
  }

  delegateApproval(memberId, delegateId) {
    if (!this.#roleByMemberId.has(memberId)) throw new PolicyRoleIndexError("ROLE_INDEX_UNKNOWN_MEMBER", "转交发起人不在角色索引中：" + memberId);
    if (!this.#roleByMemberId.has(delegateId)) throw new PolicyRoleIndexError("ROLE_INDEX_UNKNOWN_MEMBER", "转交目标不在角色索引中：" + delegateId);
    if (memberId === delegateId) throw new PolicyRoleIndexError("ROLE_INDEX_SELF_DELEGATION", "审批不能转交给自己");
    this.#delegateByMemberId.set(memberId, delegateId);
    return delegateId;
  }

  removeDelegation(memberId) { return this.#delegateByMemberId.delete(memberId); }

  // 统一成员删除 finalize 的角色索引部分：
  // 1) 把指向被删成员的审批转交重接到被删成员的后继审批人；
  //    后继不存在（被删成员自身无转交），或后继恰好是转交发起人（如删除前的二员环）时，
  //    直接解除该转交，避免出现自指（delegateApproval 禁止转交给自己）。
  // 2) 删除被删成员自己发起的转交与角色映射。
  // 幂等：重复调用无副作用；被删成员不在索引中时同样安全。
  removeMemberBindings(memberId) {
    if (typeof memberId !== "string" || memberId.length === 0) throw new PolicyRoleIndexError("ROLE_INDEX_MEMBER_INVALID", "成员 id 必须是非空字符串");
    const successor = this.#delegateByMemberId.get(memberId) ?? null;
    for (const [delegatorId, delegateId] of [...this.#delegateByMemberId.entries()]) {
      if (delegateId !== memberId) continue;
      if (successor !== null && successor !== delegatorId) this.#delegateByMemberId.set(delegatorId, successor);
      else this.#delegateByMemberId.delete(delegatorId);
    }
    this.#delegateByMemberId.delete(memberId);
    this.#roleByMemberId.delete(memberId);
    return memberId;
  }

  resolveApproverId(memberId) {
    if (!this.#roleByMemberId.has(memberId)) throw new PolicyRoleIndexError("ROLE_INDEX_UNKNOWN_MEMBER", "成员不在角色索引中：" + memberId);
    const visited = [];
    let cursor = memberId;
    while (this.#delegateByMemberId.has(cursor)) {
      if (visited.includes(cursor)) throw new PolicyRoleIndexError("ROLE_INDEX_DELEGATION_CYCLE", "审批转交链存在环路：" + [...visited, cursor].join(" -> "));
      visited.push(cursor);
      const next = this.#delegateByMemberId.get(cursor);
      if (!this.#roleByMemberId.has(next)) throw new PolicyRoleIndexError("ROLE_INDEX_DANGLING_DELEGATE", "审批转交目标不存在：" + next);
      cursor = next;
    }
    return cursor;
  }
}

// 统一的成员删除 finalize：本地删除成功（OfflineMutationQueue 结算出的 mutation.succeeded，
// 含 MEMBER_NOT_FOUND 幂等成功）与服务器删除事件（DeltaStream 的 member.removed）共用同一条路径，
// 保证"存储墓碑 + 角色索引 + 审批转交链"在一次删除确认后同步收敛。
// vault.removeMember 内部先 recordMutationSeq（记录墓碑序号）再从 #members 删除，
// 墓碑保留在 MemberVault.#mutationSeq 中供旧快照按成员过滤使用。
export function finalizeMemberRemoval(memberId, options = {}) {
  const { vault = null, policyRoleIndex = null, mutationSeq = null } = options;
  if (policyRoleIndex) policyRoleIndex.removeMemberBindings(memberId);
  if (vault) vault.removeMember(memberId, { mutationSeq: Number.isInteger(mutationSeq) ? mutationSeq : undefined });
  return memberId;
}

export class OfflineMutationQueueError extends Error {
  constructor(code, message, options = {}) {
    super(message, options);
    this.name = "OfflineMutationQueueError";
    this.code = code;
  }
}

const DEFAULT_BATCH_SIZE = 20;

export class OfflineMutationQueue {
  #transport;
  #batchSize;
  #pending = [];
  #inflight = null;
  #listeners = new Set();

  constructor(options = {}) {
    if (!options.transport || typeof options.transport.send !== "function") throw new OfflineMutationQueueError("QUEUE_TRANSPORT_REQUIRED", "离线队列需要提供 transport.send");
    this.#transport = options.transport;
    this.#batchSize = Number.isInteger(options.batchSize) && options.batchSize > 0 ? options.batchSize : DEFAULT_BATCH_SIZE;
  }

  get size() { return this.#pending.length; }
  get isFlushing() { return this.#inflight !== null; }

  listPending() {
    return this.#pending.map((mutation) => ({ id: mutation.id, kind: mutation.kind, memberIds: [...(mutation.memberIds ?? [])], createdAt: mutation.createdAt ?? null }));
  }

  enqueue(mutation) {
    if (!mutation || typeof mutation.id !== "string" || mutation.id.length === 0) throw new OfflineMutationQueueError("QUEUE_MUTATION_INVALID", "待决操作必须包含非空 id");
    if (typeof mutation.kind !== "string" || mutation.kind.length === 0) throw new OfflineMutationQueueError("QUEUE_MUTATION_INVALID", "待决操作必须包含非空 kind");
    if (this.#pending.some((item) => item.id === mutation.id)) throw new OfflineMutationQueueError("QUEUE_DUPLICATE_MUTATION", "待决操作 id 重复：" + mutation.id);
    this.#pending.push(mutation);
    return mutation.id;
  }

  subscribe(listener) {
    this.#listeners.add(listener);
    return () => this.#listeners.delete(listener);
  }

  flush() {
    if (this.#inflight) return this.#inflight;
    if (this.#pending.length === 0) return Promise.resolve({ appliedSeq: null, succeeded: [], failed: [] });
    const batch = this.#pending.slice(0, this.#batchSize);
    this.#pending = this.#pending.slice(batch.length);
    this.#inflight = this.#sendBatch(batch).finally(() => { this.#inflight = null; });
    return this.#inflight;
  }

  async #sendBatch(batch) {
    let result;
    try {
      result = await this.#transport.send(batch);
    } catch (error) {
      // 整批发送失败（如响应丢失/网络抖动）：把整批按原顺序放回队首等待重试，
      // 同时保留在途期间新入队的以及尚未进入本批的待决操作（不得用批次覆盖整个队列）。
      this.#pending = [...batch, ...this.#pending];
      throw new OfflineMutationQueueError("QUEUE_BATCH_FAILED", "批量同步失败：" + (error && error.message ? error.message : "unknown"), { cause: error });
    }
    return this.#settleBatch(batch, result);
  }

  #settleBatch(batch, result) {
    if (!result || typeof result !== "object") throw new OfflineMutationQueueError("QUEUE_RESULT_INVALID", "transport.send 必须返回对象");
    const appliedIds = new Set(Array.isArray(result.applied) ? result.applied : []);
    const appliedSeq = Number.isInteger(result.appliedSeq) ? result.appliedSeq : null;
    const idempotentById = new Map((Array.isArray(result.idempotent) ? result.idempotent : []).map((entry) => [entry.mutationId, entry]));
    const failedById = new Map((Array.isArray(result.failed) ? result.failed : []).map((entry) => [entry.mutationId, entry]));
    const succeeded = [];
    const failed = [];
    for (const mutation of batch) {
      if (appliedIds.has(mutation.id)) {
        const outcome = { mutation, result: { appliedSeq, code: null, outcome: "applied" } };
        succeeded.push(outcome);
        this.#emit({ type: "mutation.succeeded", ...outcome });
        continue;
      }
      const idempotentEntry = idempotentById.get(mutation.id);
      if (idempotentEntry) {
        if (this.#declaresIdempotentSuccess(mutation, idempotentEntry.code)) {
          const outcome = { mutation, result: { appliedSeq: Number.isInteger(idempotentEntry.appliedSeq) ? idempotentEntry.appliedSeq : appliedSeq, code: idempotentEntry.code, outcome: "idempotent" } };
          succeeded.push(outcome);
          this.#emit({ type: "mutation.succeeded", ...outcome });
          continue;
        }
        const outcome = { mutation, error: { code: idempotentEntry.code, message: idempotentEntry.message ?? "" } };
        failed.push(outcome);
        this.#emit({ type: "mutation.failed", ...outcome });
        continue;
      }
      const failedEntry = failedById.get(mutation.id);
      const error = failedEntry ? { code: failedEntry.code, message: failedEntry.message ?? "" } : { code: "QUEUE_RESULT_MISSING", message: "服务器结果缺少该待决操作" };
      const outcome = { mutation, error };
      failed.push(outcome);
      this.#emit({ type: "mutation.failed", ...outcome });
    }
    if (failed.length > 0) {
      // 结算失败的项按原顺序放回队首等待重试（失败项先于更晚入队的操作，重试顺序可预期）；
      // 保留在途期间新入队的与尚未进入本批的待决操作，不得用失败批次覆盖整个队列。
      this.#pending = [...failed.map((outcome) => outcome.mutation), ...this.#pending];
    }
    return { appliedSeq, succeeded, failed };
  }

  #declaresIdempotentSuccess(mutation, code) {
    return Array.isArray(mutation.successData) && mutation.successData.some((entry) => entry && entry.code === code && entry.behavior === "treatAsApplied");
  }

  #emit(payload) {
    for (const listener of [...this.#listeners]) {
      try { listener(payload); } catch {}
    }
  }
}

export function createOfflineMutationQueue(options) { return new OfflineMutationQueue(options); }

const MEMBER_STATUSES = new Set(["active", "invited", "suspended"]);

export class MemberVaultError extends Error {
  constructor(code, message) {
    super(message);
    this.name = "MemberVaultError";
    this.code = code;
  }
}

export function normalizeMember(input) {
  if (!input || typeof input !== "object") throw new MemberVaultError("MEMBER_INVALID", "成员记录必须是对象");
  if (typeof input.id !== "string" || input.id.trim().length === 0) throw new MemberVaultError("MEMBER_ID_INVALID", "成员 id 必须是非空字符串");
  const status = input.status ?? "active";
  if (!MEMBER_STATUSES.has(status)) throw new MemberVaultError("MEMBER_STATUS_INVALID", "未知成员状态：" + status);
  return {
    id: input.id,
    email: typeof input.email === "string" ? input.email : "",
    displayName: typeof input.displayName === "string" && input.displayName.length > 0 ? input.displayName : (typeof input.email === "string" ? input.email : input.id),
    status,
    pendingAction: input.pendingAction ?? null,
    lastError: input.lastError ?? null,
  };
}

export class MemberVault {
  #members = new Map();
  #mutationSeq = new Map();
  // 真实删除墓碑：id -> 该成员被确认删除时的序号。
  // 与 #mutationSeq 的区别：#mutationSeq 混存「存活成员的普通变更序号（快照/增量落库时记录）」
  // 与「删除序号」，不能用于判定「成员当前是否处于已删除状态」；
  // #tombstoneSeq 只在删除确认时写入，并在成员回到存活状态（upsert/restore/快照再现）时清除，
  // 供 DeltaStream.applyServerSnapshot 按成员过滤旧快照（防止旧快照复活已删除成员，
  // 同时不误伤快照中的存活成员——存活成员没有墓碑，始终随快照更新）。
  #tombstoneSeq = new Map();
  #revision = 0;
  #listeners = new Set();

  constructor(members = []) {
    for (const member of members) {
      const normalized = normalizeMember(member);
      this.#members.set(normalized.id, normalized);
    }
  }

  get revision() { return this.#revision; }

  listMembers() {
    return [...this.#members.values()].map((member) => ({ ...member })).sort((left, right) => left.id.localeCompare(right.id));
  }

  getMember(id) {
    const member = this.#members.get(id);
    return member ? { ...member } : null;
  }

  hasMember(id) { return this.#members.has(id); }

  upsertMember(input) {
    const normalized = normalizeMember(input);
    const current = this.#members.get(normalized.id);
    if (current && normalized.pendingAction === null) normalized.pendingAction = current.pendingAction;
    this.#members.set(normalized.id, normalized);
    // 成员回到存活状态（含删除后经更新的增量事件重新加入），既有墓碑随之失效。
    this.#tombstoneSeq.delete(normalized.id);
    this.#bump("member.upserted", normalized.id);
    return { ...normalized };
  }

  setPendingAction(id, action) {
    const current = this.#members.get(id);
    if (!current) return false;
    this.#members.set(id, { ...current, pendingAction: action ?? null });
    this.#bump("member.pending-changed", id);
    return true;
  }

  setLastError(id, lastError) {
    const current = this.#members.get(id);
    if (!current) return false;
    this.#members.set(id, { ...current, lastError: lastError ?? null });
    this.#bump("member.error-changed", id);
    return true;
  }

  removeMember(id, options = {}) {
    if (Number.isInteger(options.mutationSeq)) {
      // 先记录序号（普通变更序号，供增量事件按序过滤）再删除成员；
      // 同时记录真实删除墓碑（单调：仅在新序号不低于既有墓碑时更新），成员自此处于已删除状态。
      this.recordMutationSeq(id, options.mutationSeq);
      const currentTombstone = this.#tombstoneSeq.get(id);
      if (currentTombstone === undefined || options.mutationSeq >= currentTombstone) this.#tombstoneSeq.set(id, options.mutationSeq);
    }
    const removed = this.#members.delete(id);
    if (removed) this.#bump("member.removed", id);
    return removed;
  }

  restoreMember(input) {
    const normalized = normalizeMember({ ...input, pendingAction: null, lastError: null });
    this.#members.set(normalized.id, normalized);
    // 回滚复活：成员回到存活状态，墓碑失效。
    this.#tombstoneSeq.delete(normalized.id);
    this.#bump("member.restored", normalized.id);
    return { ...normalized };
  }

  replaceMembers(members) {
    // 失败原子：先完整构造并验证 next，不在构造循环中修改 #tombstoneSeq——
    // 若任一条目 normalizeMember 抛错（如 MEMBER_ID_INVALID），快照整体未落库，
    // 原成员表、删除墓碑与序号状态全部保留（否则失败快照会提前撤销删除保护，
    // 使随后的旧快照复活已确认删除且从未成功重加的成员）。
    const next = new Map();
    for (const member of members ?? []) {
      const normalized = normalizeMember(member);
      next.set(normalized.id, normalized);
    }
    // 全部条目验证通过后才提交：替换成员表，并清除最终存活成员对应的墓碑（发布落库事件之前完成）。
    this.#members = next;
    for (const id of next.keys()) this.#tombstoneSeq.delete(id);
    this.#bump("members.replaced", null);
  }

  recordMutationSeq(id, seq) {
    if (!Number.isInteger(seq) || seq < 0) throw new MemberVaultError("MEMBER_SEQ_INVALID", "变更序号必须是非负整数");
    const current = this.#mutationSeq.get(id) ?? 0;
    if (seq > current) this.#mutationSeq.set(id, seq);
    return this.#mutationSeq.get(id);
  }

  lastMutationSeqOf(id) { return this.#mutationSeq.get(id) ?? 0; }

  // 读取真实删除墓碑：成员当前处于已删除状态时返回其删除序号，否则（从未删除或已重新存活）返回 null。
  // 注意与 lastMutationSeqOf 区分：后者是普通变更序号（存活成员也有），不能判定删除状态。
  tombstoneSeqOf(id) { return this.#tombstoneSeq.has(id) ? this.#tombstoneSeq.get(id) : null; }

  subscribe(listener) {
    this.#listeners.add(listener);
    return () => this.#listeners.delete(listener);
  }

  #bump(reason, memberId) {
    this.#revision += 1;
    const event = { reason, memberId, revision: this.#revision };
    for (const listener of [...this.#listeners]) {
      try { listener(event); } catch {}
    }
  }
}

import { finalizeMemberRemoval } from "../policy/PolicyRoleIndex.js";

export class DeltaStreamError extends Error {
  constructor(code, message) {
    super(message);
    this.name = "DeltaStreamError";
    this.code = code;
  }
}

const CONNECTION_STATES = new Set(["online", "offline"]);

export class DeltaStream {
  #vault;
  #policyRoleIndex;
  #cursor = 0;
  #connectionState = "online";
  #listeners = new Set();

  constructor(options = {}) {
    if (!options.vault) throw new DeltaStreamError("DELTA_VAULT_REQUIRED", "DeltaStream 需要 MemberVault 实例");
    this.#vault = options.vault;
    this.#policyRoleIndex = options.policyRoleIndex ?? null;
  }

  get cursor() { return this.#cursor; }
  get connectionState() { return this.#connectionState; }
  isOffline() { return this.#connectionState === "offline"; }

  setConnectionState(state) {
    if (!CONNECTION_STATES.has(state)) throw new DeltaStreamError("DELTA_CONNECTION_INVALID", "未知连接状态：" + state);
    const changed = this.#connectionState !== state;
    this.#connectionState = state;
    if (changed) this.#emit({ type: "connection.changed", state });
    return state;
  }

  subscribe(listener) {
    this.#listeners.add(listener);
    return () => this.#listeners.delete(listener);
  }

  applyDelta(delta) {
    if (!delta || !Number.isInteger(delta.seq) || !Array.isArray(delta.events)) throw new DeltaStreamError("DELTA_INVALID", "增量消息必须包含整数 seq 与 events 数组");
    if (delta.seq <= this.#cursor) return { applied: false, seq: this.#cursor };
    for (const event of delta.events) this.#applyEvent(event, delta.seq);
    this.#cursor = delta.seq;
    this.#emit({ type: "delta.applied", seq: delta.seq });
    return { applied: true, seq: delta.seq };
  }

  applyServerSnapshot(snapshot) {
    if (!snapshot || !Number.isInteger(snapshot.snapshotSeq) || !Array.isArray(snapshot.members)) throw new DeltaStreamError("SNAPSHOT_INVALID", "快照必须包含整数 snapshotSeq 与 members 数组");
    // 按成员比较快照序号与该成员的「真实删除墓碑」（MemberVault.tombstoneSeqOf）：
    // 只有当前处于已删除状态、且快照数据不晚于其删除序号的成员才被跳过，防止旧快照复活已删除成员。
    // 存活成员没有墓碑（普通变更序号不算墓碑），始终进入全量替换结果，仍按快照正常更新——
    // 不会被逐成员过滤误删（replaceMembers 是全量替换语义，被跳过的成员等于从存储中移除）。
    const kept = [];
    for (const member of snapshot.members) {
      if (member && typeof member.id === "string") {
        const tombstone = this.#vault.tombstoneSeqOf(member.id);
        if (tombstone !== null && snapshot.snapshotSeq <= tombstone) continue;
      }
      kept.push(member);
    }
    this.#vault.replaceMembers(kept);
    for (const member of kept) {
      if (member && typeof member.id === "string") this.#vault.recordMutationSeq(member.id, snapshot.snapshotSeq);
    }
    this.#cursor = Math.max(this.#cursor, snapshot.snapshotSeq);
    this.#emit({ type: "snapshot.applied", seq: snapshot.snapshotSeq });
    return { applied: true, snapshotSeq: snapshot.snapshotSeq };
  }

  #applyEvent(event, seq) {
    if (!event || typeof event.type !== "string") throw new DeltaStreamError("DELTA_EVENT_INVALID", "增量事件缺少 type");
    if (event.type === "member.added" || event.type === "member.updated") {
      if (!event.member || typeof event.member.id !== "string") throw new DeltaStreamError("DELTA_EVENT_INVALID", "成员事件缺少 member.id");
      if (seq < this.#vault.lastMutationSeqOf(event.member.id)) return;
      this.#vault.upsertMember(event.member);
      this.#vault.recordMutationSeq(event.member.id, seq);
      return;
    }
    if (event.type === "member.removed") {
      if (typeof event.memberId !== "string") throw new DeltaStreamError("DELTA_EVENT_INVALID", "移除事件缺少 memberId");
      // 服务器删除事件与本地删除成功共用统一 finalize：记录墓碑、移除成员并清理角色索引与审批转交链。
      finalizeMemberRemoval(event.memberId, { vault: this.#vault, policyRoleIndex: this.#policyRoleIndex, mutationSeq: seq });
      return;
    }
    throw new DeltaStreamError("DELTA_EVENT_UNKNOWN", "未知增量事件：" + event.type);
  }

  #emit(payload) {
    for (const listener of [...this.#listeners]) {
      try { listener(payload); } catch {}
    }
  }
}

export function isMemberHidden(options = {}) {
  return !options.isOffline && (options.pendingAction ?? null) === "delete";
}

export function buildMemberRowViewModel(options = {}) {
  const member = options.member;
  if (!member) return null;
  const pendingAction = member.pendingAction ?? null;
  const isOffline = Boolean(options.isOffline);
  const hidden = isMemberHidden({ isOffline, pendingAction });
  return {
    id: member.id,
    displayName: typeof member.displayName === "string" && member.displayName.length > 0 ? member.displayName : (member.email ?? member.id),
    email: member.email ?? "",
    status: member.status ?? "active",
    pendingAction,
    hidden,
    interactive: !hidden,
    offlineIndicator: isOffline && pendingAction !== null,
    errorText: member.lastError ?? null,
  };
}

export function buildMemberListViewModel(options = {}) {
  const rows = (options.members ?? []).map((member) => buildMemberRowViewModel({ member, isOffline: options.isOffline })).filter(Boolean);
  return {
    rows,
    visibleRows: rows.filter((row) => !row.hidden),
    hiddenCount: rows.filter((row) => row.hidden).length,
  };
}

"""主控制器：``StructFolder``。

编排 ``csv_utils``（词法读取）与 ``schema_utils``（树推导 / 投影），
对外暴露 ``get_schema`` 与 ``convert`` 两个 API 契约入口，
并承担构造参数校验（delimiters / conflict_policy / type_coercion / column_aliases）。
"""

from __future__ import annotations

from collections.abc import Sequence
from typing import Dict, List, Optional

from .csv_utils import CsvSource, read_table
from .schema_utils import (
    detect_alias_cycles,
    infer_schema,
    project_row,
    validate_schema,
)

__all__ = ["StructFolder"]

#: 合法的冲突策略集合（扩展约束 A）。
_CONFLICT_POLICIES = ("error", "last", "nest_value")


class StructFolder:
    """平面分隔符表格 -> 嵌套 JSON 投影引擎的主控制器。

    参数：
        delimiters: 列名切分分隔符列表，默认 ``["_", " "]``；
        conflict_policy: 扩展约束 A，``"error"``（默认）/ ``"last"`` / ``"nest_value"``；
        type_coercion: 扩展约束 B，内联类型指令开关（见 schema_utils.infer_schema 文档）；
        column_aliases: 扩展约束 C，列名别名映射 ``dict[str, str]``，
            构造时即完成环路检测，发现环路抛 ``CircularAliasError``。
    """

    def __init__(
        self,
        delimiters: Optional[Sequence[str]] = None,
        conflict_policy: str = "error",
        type_coercion: bool = False,
        column_aliases: Optional[Dict[str, str]] = None,
    ) -> None:
        self._delimiters = self._validate_delimiters(delimiters)
        self._conflict_policy = self._validate_conflict_policy(conflict_policy)
        self._type_coercion = bool(type_coercion)
        self._aliases = self._validate_aliases(column_aliases)

    # -- 对外 API 契约 ------------------------------------------------------

    def get_schema(self, csv_source: CsvSource) -> Dict[str, object]:
        """读取 CSV 表头行，自动推导嵌套 Schema 树。

        当且仅当某非空前缀被至少 2 列共享时才提升为嵌套字典键，支持多层递归；
        ``conflict_policy="error"`` 时叶子/子树路径冲突立即抛 ``SchemaConflictError``。
        """
        header, _rows = read_table(csv_source)
        return infer_schema(
            header,
            self._delimiters,
            conflict_policy=self._conflict_policy,
            aliases=self._aliases,
            type_coercion=self._type_coercion,
        )

    def convert(
        self, csv_source: CsvSource, schema: Optional[Dict[str, object]] = None
    ) -> List[Dict[str, object]]:
        """将每行数据按 Schema 填充为嵌套字典列表。

        - ``schema`` 为 ``None``：先经 ``get_schema`` 同一路径自动推导；
        - 显式传入 Schema：先做结构校验（叶子必须映射到原始列名字符串）；
        - 输出键序与 Schema 一致（各层键按字典序稳定排序，``_self`` 最前）；
        - 带类型指令后缀的叶子在填充时完成 ``@int``/``@float``/``@bool`` 转换。
        """
        header, rows = read_table(csv_source)
        if schema is None:
            schema = infer_schema(
                header,
                self._delimiters,
                conflict_policy=self._conflict_policy,
                aliases=self._aliases,
                type_coercion=self._type_coercion,
            )
        else:
            validate_schema(schema)
        results: List[Dict[str, object]] = []
        for row in rows:
            record = dict(zip(header, row))
            results.append(project_row(schema, record))
        return results

    # -- 构造参数校验 --------------------------------------------------------

    @staticmethod
    def _validate_delimiters(
        delimiters: Optional[Sequence[str]],
    ) -> List[str]:
        if delimiters is None:
            return ["_", " "]
        if isinstance(delimiters, (str, bytes)) or not isinstance(
            delimiters, Sequence
        ):
            raise TypeError(
                "delimiters 必须是分隔符字符串序列，得到 %r" % type(delimiters).__name__
            )
        result = []
        for delim in delimiters:
            if not isinstance(delim, str) or not delim:
                raise TypeError(
                    "delimiters 元素必须是非空字符串，得到 %r" % (delim,)
                )
            result.append(delim)
        return result

    @staticmethod
    def _validate_conflict_policy(conflict_policy: str) -> str:
        if conflict_policy not in _CONFLICT_POLICIES:
            raise ValueError(
                "conflict_policy 必须是 %s 之一，得到 %r"
                % (" / ".join(repr(p) for p in _CONFLICT_POLICIES), conflict_policy)
            )
        return conflict_policy

    @staticmethod
    def _validate_aliases(column_aliases: Optional[Dict[str, str]]) -> Dict[str, str]:
        if column_aliases is None:
            return {}
        if not isinstance(column_aliases, dict):
            raise TypeError(
                "column_aliases 必须是 dict[str, str]，得到 %r"
                % type(column_aliases).__name__
            )
        for key, target in column_aliases.items():
            if not isinstance(key, str) or not isinstance(target, str):
                raise TypeError(
                    "column_aliases 的键与值都必须是 str，得到 %r -> %r" % (key, target)
                )
        # 扩展约束 C：构造（初始化）阶段即完成别名链环路检测
        detect_alias_cycles(column_aliases)
        return dict(column_aliases)

"""提供公开入口，先校验阅读速率，再解析并分发计算。"""

from typing import Optional

from . import engine, parser
from .errors import UnsupportedFormatError
from .result import ReadPulseResult


DEFAULT_WPM = 265


def _validate_rates(wpm: float, code_wpm: Optional[float] = None) -> None:
    """在任何内容解析之前拒绝非正的正文或代码阅读速率。"""
    if wpm <= 0:
        raise ValueError("wpm 必须大于 0")
    if code_wpm is not None and code_wpm <= 0:
        raise ValueError("code_wpm 必须大于 0")


def of_text(text: Optional[str], wpm: float = DEFAULT_WPM) -> ReadPulseResult:
    """按纯文本的空白分词结果估算阅读时长，不解析任何语法。"""
    _validate_rates(wpm)
    return engine.estimate(parser.parse_text(text), wpm)


def of_markdown(
    markdown_text: Optional[str],
    wpm: float = DEFAULT_WPM,
    code_wpm: Optional[float] = None,
    exclude_blockquotes: bool = False,
) -> ReadPulseResult:
    """解析 Markdown 的标题、围栏代码、图片与可选引用剥离。"""
    _validate_rates(wpm, code_wpm)
    parsed_sections = parser.parse_markdown(markdown_text, exclude_blockquotes)
    return engine.estimate(parsed_sections, wpm, code_wpm)


def of_html(
    html_text: Optional[str],
    wpm: float = DEFAULT_WPM,
    code_wpm: Optional[float] = None,
    exclude_blockquotes: bool = False,
) -> ReadPulseResult:
    """解析 HTML 的可见文字、标题、代码块、图片和嵌套引用。"""
    _validate_rates(wpm, code_wpm)
    parsed_sections = parser.parse_html(html_text, exclude_blockquotes)
    return engine.estimate(parsed_sections, wpm, code_wpm)


def of_content(
    content: Optional[str],
    format: str = "text",
    wpm: float = DEFAULT_WPM,
    code_wpm: Optional[float] = None,
    exclude_blockquotes: bool = False,
) -> ReadPulseResult:
    """根据显式格式分发到纯文本、Markdown 或 HTML 入口。"""
    # 即使纯文本忽略代码速率，也先校验通用入口收到的全部速率。
    _validate_rates(wpm, code_wpm)
    if format == "text":
        return of_text(content, wpm=wpm)
    if format == "markdown":
        return of_markdown(
            content,
            wpm=wpm,
            code_wpm=code_wpm,
            exclude_blockquotes=exclude_blockquotes,
        )
    if format == "html":
        return of_html(
            content,
            wpm=wpm,
            code_wpm=code_wpm,
            exclude_blockquotes=exclude_blockquotes,
        )
    raise UnsupportedFormatError(f"不支持的内容格式：{format!r}")

"""定义公开入口使用的格式不支持异常。"""


class UnsupportedFormatError(ValueError):
    """表示调用方指定了不受支持的内容格式。"""

"""将纯文本、Markdown 和 HTML 清洗为带独立词数的顺序章节。"""

import re
from html.parser import HTMLParser
from typing import Any, Dict, List, Optional, Tuple


_FENCE_RE = re.compile(r"^\s*(?:`{3,}|~{3,})(.*)$")
_BLOCKQUOTE_RE = re.compile(r"^\s{0,3}>")
_HEADING_RE = re.compile(r"^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$")
_IMAGE_RE = re.compile(r'!\[([^\]]*)\]\(([^)\s]+)(?:\s+"[^"]*")?\)')
_HEADING_TAGS = ("h1", "h2", "h3", "h4", "h5", "h6")


def _new_section(title: str) -> Dict[str, Any]:
    """创建只保存统计信息、不涉及阅读速率的中间章节。"""
    return {"title": title, "prose_words": 0, "code_words": 0, "image_count": 0}


class _SectionBuilder:
    """按出现顺序累积章节，并去掉没有内容的隐式引言。"""

    def __init__(self) -> None:
        self._current = _new_section("Introduction")
        self._sections = [self._current]
        self._has_heading = False

    def start_section(self, title: str) -> Dict[str, Any]:
        """为标题开启章节；只有首标题前存在实际内容才保留引言。"""
        if not self._has_heading and not (
            self._current["prose_words"]
            or self._current["code_words"]
            or self._current["image_count"]
        ):
            self._sections.clear()
        self._current = _new_section(title)
        self._sections.append(self._current)
        self._has_heading = True
        return self._current

    def add_prose(self, text: str) -> None:
        """按空白分词统计当前章节的正文。"""
        self._current["prose_words"] += len(text.split())

    def add_code(self, text: str) -> None:
        """按空白分词统计代码，避免重复计入正文。"""
        self._current["code_words"] += len(text.split())

    def add_images(self, count: int = 1) -> None:
        """记录当前章节的图片数，阶梯耗时留给计算引擎处理。"""
        self._current["image_count"] += count

    def finish(self) -> List[Dict[str, Any]]:
        """整篇零词零图时返回空章节，否则保留标题的顺序。"""
        if not any(
            section["prose_words"] or section["code_words"] or section["image_count"]
            for section in self._sections
        ):
            return []
        return self._sections


def parse_text(text: Optional[str]) -> List[Dict[str, Any]]:
    """纯文本不识别标题、图片或代码语法，只统计空白分词。"""
    builder = _SectionBuilder()
    builder.add_prose("" if text is None else text)
    return builder.finish()


def _add_markdown_prose(builder: _SectionBuilder, text: str) -> None:
    """剥离正文中的图片标记、替代文字和地址，再统计剩余正文。"""
    prose, image_count = _IMAGE_RE.subn("", text)
    builder.add_images(image_count)
    builder.add_prose(prose)


def parse_markdown(
    markdown_text: Optional[str], exclude_blockquotes: bool = False
) -> List[Dict[str, Any]]:
    """通过逐行状态机区分围栏代码、引用、标题和正文图片。"""
    builder = _SectionBuilder()
    source = "" if markdown_text is None else markdown_text
    in_code = False

    for line in source.splitlines():
        fence = _FENCE_RE.match(line)
        # 代码状态具有最高优先级，内部语法均按原样计入代码。
        if in_code:
            if fence is not None:
                in_code = False
            else:
                builder.add_code(line)
            continue

        # 围栏标记及其语言标注不计词，也支持波浪线围栏。
        if fence is not None:
            in_code = True
            continue

        quote = _BLOCKQUOTE_RE.match(line)
        if quote is not None:
            if exclude_blockquotes:
                # 丢弃整行，不让引用中的标记影响围栏或章节状态。
                continue
            # 保留引用时只处理正文，不重新识别引用内的标题和围栏。
            _add_markdown_prose(builder, line[quote.end():])
            continue

        heading = _HEADING_RE.match(line)
        if heading is not None:
            title = heading.group(2).strip()
            builder.start_section(title)
            builder.add_prose(title)
            continue

        # 行内代码和四空格缩进均留在正文分词规则中。
        _add_markdown_prose(builder, line)

    return builder.finish()


class _HTMLContentParser(HTMLParser):
    """利用嵌套计数器清洗 HTML，并收集标题的完整可见文本。"""

    def __init__(self, exclude_blockquotes: bool) -> None:
        super().__init__(convert_charrefs=True)
        self._builder = _SectionBuilder()
        self._exclude_blockquotes = exclude_blockquotes
        self._pre_depth = 0
        self._blockquote_depth = 0
        self._ignored_depths = {"script": 0, "style": 0}
        self._heading_tag: Optional[str] = None
        self._heading_section: Optional[Dict[str, Any]] = None
        self._heading_parts: List[str] = []

    def _inside_ignored_element(self) -> bool:
        """判断是否位于应整段剥离的脚本或样式元素内。"""
        return any(self._ignored_depths.values())

    def _inside_excluded_quote(self) -> bool:
        """引用计数大于零时剥离整棵引用子树。"""
        return self._exclude_blockquotes and self._blockquote_depth > 0

    def _finish_heading(self) -> None:
        """将各段标题文字合并，避免内嵌标签使标题被覆盖。"""
        if self._heading_section is not None:
            self._heading_section["title"] = "".join(self._heading_parts).strip()
        self._heading_tag = None
        self._heading_section = None
        self._heading_parts = []

    def handle_starttag(
        self, tag: str, attrs: List[Tuple[str, Optional[str]]]
    ) -> None:
        """按剥离、嵌套容器、代码、图片和标题的优先级处理开标签。"""
        # HTMLParser 已把标签名转为小写，属性不参与词数统计。
        if tag in self._ignored_depths:
            self._ignored_depths[tag] += 1
            return
        if self._inside_ignored_element():
            return

        if tag == "blockquote":
            self._blockquote_depth += 1
            return
        if tag == "pre":
            self._pre_depth += 1
            return
        if self._inside_excluded_quote() or self._pre_depth > 0:
            return

        if tag == "img":
            self._builder.add_images()
            return
        if tag in _HEADING_TAGS:
            self._finish_heading()
            self._heading_tag = tag
            self._heading_section = self._builder.start_section("")
            self._heading_parts = []

    def handle_endtag(self, tag: str) -> None:
        """配对嵌套容器并结束当前标题，冗余闭标签不会产生负计数。"""
        if tag in self._ignored_depths:
            self._ignored_depths[tag] = max(0, self._ignored_depths[tag] - 1)
            return
        if self._inside_ignored_element():
            return

        if tag == "blockquote":
            self._blockquote_depth = max(0, self._blockquote_depth - 1)
            return
        if tag == "pre":
            self._pre_depth = max(0, self._pre_depth - 1)
            return
        if self._inside_excluded_quote() or self._pre_depth > 0:
            return
        if tag == self._heading_tag:
            self._finish_heading()

    def handle_data(self, data: str) -> None:
        """仅统计可见文字，代码和正文互斥，标题同时收集展示文本。"""
        if self._inside_ignored_element() or self._inside_excluded_quote():
            return
        if self._pre_depth > 0:
            self._builder.add_code(data)
            return
        self._builder.add_prose(data)
        if self._heading_section is not None:
            self._heading_parts.append(data)

    def handle_comment(self, data: str) -> None:
        """所有 HTML 注释均不产生文字、图片或章节。"""
        return

    def finish(self) -> List[Dict[str, Any]]:
        """完成输入处理，也为未显式关闭的标题保存已收集的文字。"""
        self.close()
        self._finish_heading()
        return self._builder.finish()


def parse_html(
    html_text: Optional[str], exclude_blockquotes: bool = False
) -> List[Dict[str, Any]]:
    """解析完整 HTML，自动解码实体后输出与 Markdown 相同的结构。"""
    parser = _HTMLContentParser(exclude_blockquotes)
    parser.feed("" if html_text is None else html_text)
    return parser.finish()
